SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE (NOT (("public"."author"."id") = ANY(('{1,3,6}')::integer[])))   ORDER BY "id" ASC NULLS LAST  ) AS "_root.base"    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
